Item.method_code:
const aml = '<AML><Item type=\'Method\' action=\'cmf_GetViews\'><item_type_id>' + inArgs.itemTypeId + '</item_type_id></Item></AML>';
const response = aras.applyAML(aml);
const xmldom = aras.createXMLDocument();
xmldom.loadXML(response);
const docTypeNode = xmldom.selectSingleNode('Result/Item[@type=\'cmf_ContentType\']');

const spreadsheetViews = xmldom.selectNodes('Result/Item[@type=\'cmf_TabularView\']');
const viewCollection = [];
const emptyObject = {text: ''};
for (let i = 0; i < spreadsheetViews.length; i++) {
	viewCollection.push({
		id: (spreadsheetViews[i].selectSingleNode('id') || emptyObject).text,
		name: (spreadsheetViews[i].selectSingleNode('name') || emptyObject).text,
		label: (spreadsheetViews[i].selectSingleNode('label') || emptyObject).text,
		docTypeId: docTypeNode.getAttribute('id'),
		viewId: (spreadsheetViews[i].selectSingleNode('id') || emptyObject).text,
		itemId: inArgs.itemId
	});
}
return viewCollection;
